import test from 'node:test';
import assert from 'node:assert/strict';
import {encode,decode,UNITS} from '../source/verified-foundation-address.mjs';
import {sixForGate,gateForSix,unicodeForGate} from '../source/king-wen-fuxi-map.mjs';
import {resolvePosition,expressPosition,changeAtPosition,viewPosition,PositionedStateSpace,perspective} from '../source/positioned-state-space.mjs';
const here={gate:1,line:2,color:3,tone:4,base:5,dimension:'Design',planet:1,zodiac:8,house:10,axis:'Vertical'};
test('existing micro hierarchy exhausts all 69,120 unique reversible positions',()=>{const seen=new Set();for(let i=0;i<UNITS;i++){const q=decode(i);assert.equal(encode(q),i);seen.add(JSON.stringify(q));}assert.equal(seen.size,69120);});
test('user-source King Wen/Fu Xi mapping is 64x reversible, including glyphs',()=>{const states=new Set();for(let gate=1;gate<=64;gate++){const six=sixForGate(gate);assert.equal(gateForSix(six),gate);states.add(six);assert.equal(unicodeForGate(gate).codePointAt(0),0x4DC0+gate-1);}assert.equal(states.size,64);assert.equal(sixForGate(1),63);assert.equal(sixForGate(2),0);});
test('all 384 single-line transitions map to valid King Wen states and back',()=>{let count=0;for(let gate=1;gate<=64;gate++)for(let line=1;line<=6;line++){const a={...here,gate};const t=changeAtPosition(a,'line',line);assert.equal(t.to.position.gate>=1&&t.to.position.gate<=64,true);assert.equal(changeAtPosition(t.to.position,'line',line).to.position.gate,gate);count++;}assert.equal(count,384);});
test('all 4,096 movement masks are reversible',()=>{for(let gate=1;gate<=64;gate++)for(let mask=0;mask<64;mask++){const a={...here,gate},t=changeAtPosition(a,'mask',mask),back=changeAtPosition(t.to.position,'mask',mask);assert.deepEqual(back.to.position,a);}});
test('full positional context retains house, axis, dimension and source-defined qualities',()=>{const p=resolvePosition(here);assert.equal(p.microIndex,encode(here));assert.equal(p.position.house,10);assert.equal(p.position.axis,'Vertical');const x=expressPosition(here);assert.equal(x.position.hexagram.six,63);assert.ok(x.shape.vertices>=3);assert.ok(x.sound.frequencyHz>0);assert.equal(x.sound.timbre,'square');assert.equal(x.color.layer,'frame');assert.equal(x.sound.rhythmicSlot,9);});
test('perspective changes reading without changing underlying identity; inverse restores',()=>{const p=perspective([5,4,3,2,1,0],0b101010);const viewed=viewPosition(here,p);assert.deepEqual(viewed.identity,here);assert.equal(viewed.view.position.line,5);assert.equal(viewed.view.position.house,10);assert.equal(viewed.view.position.dimension,'Design');assert.equal(resolvePosition(here).hexagram.gate,1);});
test('relocation and I Ching transitions journaled; checkpoint survives restart and refuses tamper',()=>{const world=new PositionedStateSpace(here);world.change('line',1);world.relocate({...world.current().position,house:9,axis:'Horizontal'});world.change('complement');const cp=world.checkpoint(),restored=PositionedStateSpace.restore(cp);assert.deepEqual(restored.current(),world.current());assert.deepEqual(restored.history(),world.history());assert.equal(world.history().length,4);const bad=structuredClone(cp);bad.journal[1].to.gate=99;assert.throws(()=>PositionedStateSpace.restore(bad),/proof mismatch|history continuity/);});
test('invalid coordinates rejected without silent clamping or invented context',()=>{for(const change of [{gate:0},{line:7},{base:6},{house:13},{planet:14},{dimension:'FOO'},{axis:'Other'}])assert.throws(()=>resolvePosition({...here,...change}));});
